import rili from '@/component/rili.vue';
import bolang from '@/component/bolang.vue';
import orderItem from '../order/orderItem.vue';

export default {
	data() {
		return {
			familyId: '',
			orderList: [],
			isPageScroll: false, // 页面是否在滚动
			timer: null
		};
	},

	onLoad() {
		const { familyId } = this.$store.state.userInfo;
		this.familyId = familyId;

		this.getOrderList();
	},

	onShow() {
		if (this.$store.state.bookkeepingSuccess) {
			this.getOrderList();
			this.$store.commit('SETBOOKKEEPING', false);
		}
	},

	onPageScroll() {
		this.isPageScroll = true;

		if (this.timer) {
			clearTimeout(this.timer);
		}
		// 停止滚动2s后出现
		this.timer = setTimeout(() => {
			this.isPageScroll = false;
		}, 2000);
	},

	// 下拉刷新
	async onPullDownRefresh() {
		this.getOrderList();
		uni.stopPullDownRefresh();
	},

	methods: {
		getOrderList() {
			this.$api({
				url: '/order/list',
				data: {
					page: 1,
					pageSize: 10
				}
			})
				.then(res => {
					if (res && res.list) {
						this.orderList = res.list;
					}
				})
				.catch(e => {
					this.$common.toast(e.msg);
				})
				.finally();
		},

		// 点击记账按钮
		bookkeepEvt() {
			// 如果按钮靠边隐藏了，点击让他出来
			if (this.isPageScroll) {
				this.isPageScroll = false;
				return;
			}

			uni.navigateTo({
				url: '/pages/bookkeep/index'
			});
		}
	},

	components: {
		rili,
		bolang,
		orderItem
	}
};
